package vn.vinhkhang.warehouse;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:h2:mem:deferred_vehicle;DB_CLOSE_DELAY=-1"})
class DeferredVehicleTest {
 @Autowired Api core;@Autowired FirstSetup setup;@Autowired VehicleReceipts receipts;@Autowired Operations operations;@Autowired SalesShipments print;@Autowired JdbcTemplate db;
 @Test void blankFieldsReceiveShipAndFillSerialsLater(){
 setup.create(Map.of("username","test","display_name","Test","password","1","confirm_password","1","account_kind","STORE"));String t=core.login(new Api.Login("test","1")).get("token").toString();long model=core.create("models",t,Map.of("code","M","name","Mẫu xe thử")).get("id");
 receipts.create(t,Map.of("code","NK","source","Nhập thử","vehicles",List.of(Map.of("model_id",model,"vehicle_type","REGISTERED","quantity",2))));var vs=core.list("vehicles",t);assertEquals(2,vs.size());long id=((Number)vs.getFirst().get("ID")).longValue();assertNull(vs.getFirst().get("FRAME_NUMBER"));assertNull(vs.getFirst().get("PURCHASE_UNIT_COST"));
 long ship=core.ship(t,Map.of("code","XK","customer","Khách thử","vehicle_type","REGISTERED","vehicles",List.of(Map.of("id",id,"color","Xanh ngọc","unit_price",1234567)))).get("id");assertEquals("Xanh ngọc",db.queryForObject("SELECT color FROM vehicles WHERE id=?",String.class,id));String html=print.print(t,ship).get("html");assertTrue(html.contains("Xanh ngọc"));assertFalse(html.contains("1.234.567"));assertFalse(html.contains("Đơn giá"));assertFalse(html.contains("Thành tiền"));
 operations.update(t,"vehicles",id,Map.of("model_id",model,"vehicle_type","REGISTERED","color","Xanh ngọc","frame_number","FRAME-LATER","motor_number","MOTOR-LATER"));assertEquals("FRAME-LATER",db.queryForObject("SELECT frame_number FROM vehicles WHERE id=?",String.class,id));assertNull(db.queryForObject("SELECT purchase_unit_cost FROM vehicles WHERE id=?",java.math.BigDecimal.class,id));assertTrue(print.print(t,ship).get("html").contains("FRAME-LATER"));long other=((Number)vs.get(1).get("ID")).longValue();assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->operations.update(t,"vehicles",other,Map.of("model_id",model,"vehicle_type","REGISTERED","color","","frame_number","FRAME-LATER","motor_number","MOTOR-OTHER")));
 }
}
